gid_t real_gid, eff_gid, save_gid;
int status;

// Retrieve Real, Effective, Saved group IDs (32-bit capable)
status = getresgid32(&real_gid, &eff_gid, &save_gid);

if (status == 0) {
    /* Success: IDs loaded */
} else {
    /* status == -1 on error */
    switch (errno) {
        case EFAULT:
            /* Pointer arguments invalid */
            break;
        default:
            break;
    }
}
